-- Phase 2D — build the DOJG-backed canonical Grammar Library.
-- Rerunnable. Existing completed guides and personal study data are preserved.
--
-- This migration:
--   * permits jlpt_level to be NULL for reference-backed grammar concepts;
--   * creates any missing canonical guides from the reviewed DOJG catalogue;
--   * does not overwrite existing guide explanations;
--   * links every reviewed DOJG source entry through grammar_dictionary_references.
--
-- Requires:
--   20260910_phase2b_dojg_reference_links.sql

begin;

-- DOJG does not provide JLPT levels. A NULL level is more accurate than
-- assigning a fabricated level merely to satisfy the earlier schema.
alter table public.japanese_grammar_guides
  alter column jlpt_level drop not null;

with catalogue(canonical,meaning,summary) as (values
    ('〜かもしれない','Can''t tell if ~','Can''t tell if ~'),
    ('〜がる','An auxiliary verb attached to a psychological/physiological adjective meaning a person other than the speaker shows signs of ~','An auxiliary verb attached to a psychological/physiological adjective meaning a person other than the speaker shows signs of ~'),
    ('〜ことにする','A volitional decision to do something is made.','A volitional decision to do something is made.'),
    ('〜ごろ','Approximately (with a specific point of time).','Approximately (with a specific point of time).'),
    ('〜し','A conjunction to indicate ‘and’ in an emphatic way.','A conjunction to indicate ‘and’ in an emphatic way.'),
    ('〜たい','An auxiliary adjective which expresses a desire to do something.','An auxiliary adjective which expresses a desire to do something.'),
    ('〜たら','A subordinate conjunction which indicates that the action/state expressed by the main clause in a sentence takes place after the action/state expressed by the subordinate clause.','A subordinate conjunction which indicates that the action/state expressed by the main clause in a sentence takes place after the action/state expressed by the subordinate clause.'),
    ('〜たらどうですか','A phrase which expresses a suggestion (literally: How would you feel if you do something?)','A phrase which expresses a suggestion (literally: How would you feel if you do something?)'),
