    ('〜で（基準量）','A particle which indicates a basic quantity, for each of which certain amount is associated.','A particle which indicates a basic quantity, for each of which certain amount is associated.'),
    ('である','A copula which is used in formal writing and formal speech.','A copula which is used in formal writing and formal speech.'),
    ('〜であろう','An auxiliary which indicates the writer''s conjecture which is not based on any particular information or evidence.','An auxiliary which indicates the writer''s conjecture which is not based on any particular information or evidence.'),
    ('ては','A conjunction which presents an action/state as a topic about which a negative comment is given.','A conjunction which presents an action/state as a topic about which a negative comment is given.'),
    ('〜て初めて','A phrase which expresses the idea that someone does something or something happens only after something else happens or something else is done.','A phrase which expresses the idea that someone does something or something happens only after something else happens or something else is done.'),
    ('〜ということは','A phrase which changes a sentence into a topic noun clause.','A phrase which changes a sentence into a topic noun clause.'),
    ('というのに','A conjunction to indicate that an action/state takes place quite contrary to one''s expectation.','A conjunction to indicate that an action/state takes place quite contrary to one''s expectation.'),
    ('〜というのは〜ことだ','A structure which is used in interpreting, explaining, or defining a word, a phrase, or a sentence.','A structure which is used in interpreting, explaining, or defining a word, a phrase, or a sentence.'),
    ('〜というより（は）','A phrase that is used to indicate more accurate characterisation of someone or something.','A phrase that is used to indicate more accurate characterisation of someone or something.'),
    ('〜という風に','A phrase which expresses a manner or a way in which someone does something.','A phrase which expresses a manner or a way in which someone does something.'),
    ('どうせ','An adverb that indicates the speaker/writer''s feeling that no matter what s/he does or how s/he does it, the situation will not change.','An adverb that indicates the speaker/writer''s feeling that no matter what s/he does or how s/he does it, the situation will not change.'),
    ('とうとう','An adverb that is used to express the eventual arrival of an expected situation.','An adverb that is used to express the eventual arrival of an expected situation.'),
    ('どうも','An adverb to indicate that one cannot make a definite statement about something due to lack of hard evidence.','An adverb to indicate that one cannot make a definite statement about something due to lack of hard evidence.'),
    ('とかで','A conjunction that is used to give an uncertain reason for something.','A conjunction that is used to give an uncertain reason for something.'),
    ('ところ','A dependent noun which is used to express the idea that when someone did something, something took place as the result.','A dependent noun which is used to express the idea that when someone did something, something took place as the result.'),
    ('ところが','A conjunction which is used to present what in fact happened or what is in fact the case when something else was/is expected.','A conjunction which is used to present what in fact happened or what is in fact the case when something else was/is expected.'),
    ('どころか','A conjunction indicating that someone/something is very far from an expected state.','A conjunction indicating that someone/something is very far from an expected state.'),
    ('〜とする（仮定）','A phrase indicating that someone assumes something.','A phrase indicating that someone assumes something.'),
    ('〜とする（感覚）','To have a sensory or psychological experience.','To have a sensory or psychological experience.'),
    ('〜となる','A phrase which expresses the idea that someone or something becomes something.','A phrase which expresses the idea that someone or something becomes something.'),
    ('〜となると','A phrase which expresses the idea "when it comes to" or "if it is true that".','A phrase which expresses the idea "when it comes to" or "if it is true that".'),
    ('〜とは限らない','A phrase which expresses the idea "not necessarily".','A phrase which expresses the idea "not necessarily".'),
    ('とも','A conjunction in written Japanese that is used to express a concession.','A conjunction in written Japanese that is used to express a concession.'),
    ('〜どんなに〜（こと）か','A structure that indicates an exclamation about the degree to which an action or state takes/took place.','A structure that indicates an exclamation about the degree to which an action or state takes/took place.'),
    ('〜と共に','A phrase which is used to express the idea that A and B share a common property or do the same thing together, that two things take place at the same time, or that someone or something possesses two properties.','A phrase which is used to express the idea that A and B share a common property or do the same thing together, that two things take place at the same time, or that someone or something possesses two properties.'),
    ('〜と同時に','A phrase which is used to express the idea that someone does something or something takes place at the same time as another action or event, or that someone or something is in two states simultaneously.','A phrase which is used to express the idea that someone does something or something takes place at the same time as another action or event, or that someone or something is in two states simultaneously.'),
    ('〜と言うと','A phrase which is used when something which someone has mentioned causes an involuntary response.','A phrase which is used when something which someone has mentioned causes an involuntary response.'),
    ('〜と言っても','A phrase which is used to clarify a statement in the preceding discourse which might be misleading.','A phrase which is used to clarify a statement in the preceding discourse which might be misleading.'),
    ('なあ','An exclamatory sentential particle which is used in informal male speech.','An exclamatory sentential particle which is used in informal male speech.'),
    ('ないことも / はない','A double negative phrase used to make a conditional affirmative statement.','A double negative phrase used to make a conditional affirmative statement.'),
    ('なかなか','An adverb used to indicate the speaker''s feelings that something is impressive or his annoyance at slowness or difficulty in achieving something.','An adverb used to indicate the speaker''s feelings that something is impressive or his annoyance at slowness or difficulty in achieving something.'),
    ('なく','a continuative form of ない used in written Japanese (to indicate a reason/cause for what follows if ない is attached to Adjective (い/な) and contrast if it is attached to a Noun+Copula).','a continuative form of ない used in written Japanese (to indicate a reason/cause for what follows if ない is attached to Adjective (い/な) and contrast if it is attached to a Noun+Copula).'),
    ('なしでは','If something/someone is missing.','If something/someone is missing.'),
    ('〜などと','A compound particle that indicates an approximate quote of words or ideas.','A compound particle that indicates an approximate quote of words or ideas.'),
    ('〜ならない','A phrase that is used to express insurmountable psychological or physical feelings.','A phrase that is used to express insurmountable psychological or physical feelings.'),
    ('〜なり〜なり','A phrase to indicate two representative choices/examples.','A phrase to indicate two representative choices/examples.'),
    ('なりに','In a way/style that is proper to someone/something.','In a way/style that is proper to someone/something.'),
    ('〜に（終助詞）','A sentence final particle that expresses the speaker''s feeling of great regret or sympathy.','A sentence final particle that expresses the speaker''s feeling of great regret or sympathy.'),
    ('〜において/おける','A compound particle which indicates the place of an action/event, a state or time.','A compound particle which indicates the place of an action/event, a state or time.'),
    ('について','Concerning something/someone.','Concerning something/someone.'),
    ('〜につき','A compound particle which expresses a rate or ratio.','A compound particle which expresses a rate or ratio.'),
    ('〜につれて/つれ','A phrase used to indicate that a change occurs in accordance with another simultaneous change.','A phrase used to indicate that a change occurs in accordance with another simultaneous change.'),
    ('にとって','From the standpoint of; so far as someone (or something) is concerned.','From the standpoint of; so far as someone (or something) is concerned.'),
    ('〜になると','A phrase that expresses the time when an uncontrollable state or a habitual action occurs.','A phrase that expresses the time when an uncontrollable state or a habitual action occurs.'),
    ('には','A conjunction/compound particle to indicate a purpose for doing something.','A conjunction/compound particle to indicate a purpose for doing something.'),
    ('〜にほかならない','A phrase that is used to indicate that an action/state mentioned in the topic phrase or clause is nothing but something.','A phrase that is used to indicate that an action/state mentioned in the topic phrase or clause is nothing but something.'),
    ('にもかかわらず','Without any relation to a preceding event/situation.','Without any relation to a preceding event/situation.'),
    ('〜によって/より','A particle that indicates means, cause, agent of passive sentence, or dependency on a situation.','A particle that indicates means, cause, agent of passive sentence, or dependency on a situation.'),
    ('〜に代わって','A compound particle to express replacement or substitution of a regular person/thing by someone/something.','A compound particle to express replacement or substitution of a regular person/thing by someone/something.'),
    ('に反して/反する','Contrary to or in contrast to.','Contrary to or in contrast to.'),
    ('に基づいて/基づく','With something as a basis.','With something as a basis.'),
    ('に対して/対する','Regarding something/someone one opposes, compares, or shows interest in regarding something/someone one opposes, compares or shows interest in.','Regarding something/someone one opposes, compares, or shows interest in regarding something/someone one opposes, compares or shows interest in.'),
    ('〜に当たって/当たり','A compound particle that indicates occasion of doing something or of having done something in formal Japanese.','A compound particle that indicates occasion of doing something or of having done something in formal Japanese.'),
    ('に従って/従い','Something spontaneously and gradually occurs in accordance with some change.','Something spontaneously and gradually occurs in accordance with some change.'),
    ('に比べると/比べて','If we compare (it) with/to; comparing (it) with.','If we compare (it) with/to; comparing (it) with.'),
    ('に過ぎない','Something or someone is nothing more than what is stated in terms of amount, degree, status, significance, etc.','Something or someone is nothing more than what is stated in terms of amount, degree, status, significance, etc.'),
    ('に関して/関する','Related to.','Related to.'),
    ('〜に限って','A compound particle to show that only X is different from others.','A compound particle to show that only X is different from others.'),
    ('に限らず','Not limiting something to ~.','Not limiting something to ~.'),
    ('ぬ','An archaic auxiliary that indicates negation.','An archaic auxiliary that indicates negation.'),
    ('〜ねばならない','A phrase that indicates duty, obligation or necessity.','A phrase that indicates duty, obligation or necessity.'),
    ('のこと','Things of/about.','Things of/about.'),
    ('のことだから','Because it is a matter of X with which/whom something is habitually the case.','Because it is a matter of X with which/whom something is habitually the case.'),
    ('〜のは〜のことだ','A structure which focuses on a time when something takes place.','A structure which focuses on a time when something takes place.'),
    ('〜のみ','A particle which expresses a limit imposed upon an action, event, or a state.','A particle which expresses a limit imposed upon an action, event, or a state.'),
    ('の上では','As far as ~ is concerned.','As far as ~ is concerned.'),
    ('の下で','Under some object; under the control or influence of someone or something.','Under some object; under the control or influence of someone or something.'),
    ('〜の関係で','A phrase indicating that something takes place or does not take place because of something.','A phrase indicating that something takes place or does not take place because of something.'),
    ('〜は（強調）','A particle which emphatically affirms or negates the proposition represented by the preceding verbal and other related elements.','A particle which emphatically affirms or negates the proposition represented by the preceding verbal and other related elements.'),
    ('は言うまでもなく','An adverbial phrase that conveys the meaning of ''not to speak of something/someone''.','An adverbial phrase that conveys the meaning of ''not to speak of something/someone''.'),
    ('〜べきだ','An auxiliary which expresses the speaker''s judgment that someone/something should do something or should be in some state.','An auxiliary which expresses the speaker''s judgment that someone/something should do something or should be in some state.'),
    ('〜まい','An auxiliary which expresses the speaker''s negative volition or conjecture.','An auxiliary which expresses the speaker''s negative volition or conjecture.'),
    ('まさか','An adverb that indicates the speaker''s strong belief that something is not expected to (have) become a reality.','An adverb that indicates the speaker''s strong belief that something is not expected to (have) become a reality.'),
    ('〜ましだ','A phrase indicating that although someone/something (or some situation) is not satisfactory it is better than someone/something else.','A phrase indicating that although someone/something (or some situation) is not satisfactory it is better than someone/something else.'),
    ('または','A conjunction which connects two choices or possibilities expressed by noun phrases or sentences.','A conjunction which connects two choices or possibilities expressed by noun phrases or sentences.'),
    ('までもない','There is no point in going as far as to do something.','There is no point in going as far as to do something.'),
    ('みせる','The speaker''s strong determination to achieve something for others to see.','The speaker''s strong determination to achieve something for others to see.'),
    ('やっと','An adverb to indicate that something desirable has been finally achieved or will be eventually achieved though with great difficulty.','An adverb to indicate that something desirable has been finally achieved or will be eventually achieved though with great difficulty.'),
    ('やる（移動・使役）','To cause something/someone to move to a place or to do/eat/drink something.','To cause something/someone to move to a place or to do/eat/drink something.'),
    ('〜てやる（強行・迷惑）','An auxiliary verb which expresses the idea that someone does something undesirable to someone else when he/she knows his/her action will cause hardship or trouble.','An auxiliary verb which expresses the idea that someone does something undesirable to someone else when he/she knows his/her action will cause hardship or trouble.'),
    ('〜よう（方法）','A noun forming suffix which means a way (of doing something).','A noun forming suffix which means a way (of doing something).'),
    ('〜よう（推量）','An auxiliary verb that expresses the writer''s conjecture about some potentiality or his certainty about a given state of affairs.','An auxiliary verb that expresses the writer''s conjecture about some potentiality or his certainty about a given state of affairs.'),
    ('〜ろくに〜ない','A structure that is used to indicate that something animate does not or cannot do something satisfactorily/sufficiently/properly.','A structure that is used to indicate that something animate does not or cannot do something satisfactorily/sufficiently/properly.'),
    ('〜わけがない','A phrase which negates the existence of a reason to believe that someone does something or is in some state, or that something takes place; or which negates a possibility of someone''s doing something or being in some state, or something''s taking place.','A phrase which negates the existence of a reason to believe that someone does something or is in some state, or that something takes place; or which negates a possibility of someone''s doing something or being in some state, or something''s taking place.'),
    ('〜わけにはいかない','A phrase which is used to indicate that one cannot do something due to an external circumstance.','A phrase which is used to indicate that one cannot do something due to an external circumstance.'),
    ('〜をはじめ（として）','A phrase that is used to give a primary example.','A phrase that is used to give a primary example.'),
    ('〜を通して','A compound particle that is used to indicate a medium through which something is done or time through which something takes place.','A compound particle that is used to indicate a medium through which something is done or time through which something takes place.'),
    ('〜一方で（は） 〜 他方で（は）','A structure used to describe two concurring, contrastive actions/states of someone or something.','A structure used to describe two concurring, contrastive actions/states of someone or something.'),
    ('〜上','A suffix which indicates the idea of "from the viewpoint of," "for the sake of," "for the reason," or "in terms of".','A suffix which indicates the idea of "from the viewpoint of," "for the sake of," "for the reason," or "in terms of".'),
    ('上（に）','A conjunction which introduces an additional, emphatic statement.','A conjunction which introduces an additional, emphatic statement.'),
    ('以上（は）','A conjunction indicating the speaker/writer''s feeling that there should be a very strong logical/natural connection between wht precedes the conjunction and what follows it.','A conjunction indicating the speaker/writer''s feeling that there should be a very strong logical/natural connection between wht precedes the conjunction and what follows it.'),
    ('以外','A dependent noun which means "something/someone other than".','A dependent noun which means "something/someone other than".'),
    ('何しろ','An adverb that indicates the speaker''s emotive feeling about some extreme state of affairs.','An adverb that indicates the speaker''s emotive feeling about some extreme state of affairs.'),
    ('〜何でも','A phrase that indicates the speaker''s uncertainty about something.','A phrase that indicates the speaker''s uncertainty about something.'),
    ('〜例の','A phrase which signals that the referent of the following noun phrase is definite and that the speaker expects the hearer to understand what the referent is.','A phrase which signals that the referent of the following noun phrase is definite and that the speaker expects the hearer to understand what the referent is.'),
    ('〜分','A suffix which indicates the amount of something.','A suffix which indicates the amount of something.'),
    ('〜得る （うる・える）','An auxiliary verb that expresses possibility.','An auxiliary verb that expresses possibility.'),
    ('必ずしも','An adverb that indicates that the proposition expressed in the sentence is not always true.','An adverb that indicates that the proposition expressed in the sentence is not always true.'),
    ('思われる','A verb that indicates what the speaker/writer feels spontaneously or his/her hesitation about asserting himself/herself.','A verb that indicates what the speaker/writer feels spontaneously or his/her hesitation about asserting himself/herself.'),
    ('〜方をする','A phrase to indicate a manner of doing something.','A phrase to indicate a manner of doing something.'),
    ('来','During a certain amount of time (something has continued up until the moment of speech or something has never been like the current state).','During a certain amount of time (something has continued up until the moment of speech or something has never been like the current state).'),
    ('次第','A conjunction/noun to express that an action indicated by a preceding verb or an action implied by a preceding noun is a prerequisite for another action.','A conjunction/noun to express that an action indicated by a preceding verb or an action implied by a preceding noun is a prerequisite for another action.'),
    ('点（で）','A noun which expresses the idea of "a point of argument; a point of evaluation; a point of view".','A noun which expresses the idea of "a point of argument; a point of evaluation; a point of view".'),
    ('〜目','A suffix which represents an ordinal number.','A suffix which represents an ordinal number.'),
    ('〜確かに〜が','A structure which expresses the idea "indeed ~ but".','A structure which expresses the idea "indeed ~ but".'),
    ('結果','A noun which expresses the idea "as a result of".','A noun which expresses the idea "as a result of".'),
    ('結構','An adverb that indicates that something exceeds the speaker''s and/or hearer''s expectation to a considerable degree.','An adverb that indicates that something exceeds the speaker''s and/or hearer''s expectation to a considerable degree.'),
    ('逆に','An adverb to introduce an event which takes place contrary to one''s expectation/intention, or an action or event which is converse to that stated in the preceding sentence or clause.','An adverb to introduce an event which takes place contrary to one''s expectation/intention, or an action or event which is converse to that stated in the preceding sentence or clause.'),
    ('途端（に）','A noun/adverb which expresses the idea that ''something occurred the moment someone did something or something took place''.','A noun/adverb which expresses the idea that ''something occurred the moment someone did something or something took place''.'),
    ('通り（に）','A dependent noun which expresses the idea that someone does something or something takes place in the same way as something else.','A dependent noun which expresses the idea that someone does something or something takes place in the same way as something else.'),
    ('〜限り（条件・範囲）','A conjunction which expresses the idea "as long as (a certain condition is met)" or "as long as (= to the extent)".','A conjunction which expresses the idea "as long as (a certain condition is met)" or "as long as (= to the extent)".'),
    ('〜限り（期限・限度）','A suffix which expresses the idea of "(last) only until" or "limited".','A suffix which expresses the idea of "(last) only until" or "limited".'),
    ('際（に）','On the special occasion of/when.','On the special occasion of/when.'),
    ('〜面','A suffix which forms a compound that means a side of X, or an aspect of X.','A suffix which forms a compound that means a side of X, or an aspect of X.'),
    ('風に','With an appearance/style/tone/manner of ~.','With an appearance/style/tone/manner of ~.'),
    ('〜だけ','A particle which expresses a limit imposed upon something that is growing and expanding.','A particle which expresses a limit imposed upon something that is growing and expanding.'),
    ('〜くらい','Approximate quantity or extent.','Approximate quantity or extent.'),
    ('〜ことになる','An event takes place as if spontaneously, irrespective of the speaker''s volition.','An event takes place as if spontaneously, irrespective of the speaker''s volition.'),
    ('〜ほど','A particle which indicates an extent or a degree to which someone/something does something or is in some state.','A particle which indicates an extent or a degree to which someone/something does something or is in some state.'),
    ('〜わけだ（論理的帰結）','The speaker''s conclusion obtained through deductive, logical judgment or calculation on the basis of what he has heard or read.','The speaker''s conclusion obtained through deductive, logical judgment or calculation on the basis of what he has heard or read.'),
    ('〜間','The space between two temporal or physical points.','The space between two temporal or physical points.'),
    ('〜ば〜ほど','A structure indicating that something happens in proportion to the increase of extent/degree of action or state.','A structure indicating that something happens in proportion to the increase of extent/degree of action or state.'),
    ('〜わけだ（事実の提示・強調）','A phrase which presents a fact or truth known to the hearer as an introduction to a following statement, or which gives emphasis to a fact or truth which the hearer might not know.','A phrase which presents a fact or truth known to the hearer as an introduction to a following statement, or which gives emphasis to a fact or truth which the hearer might not know.'),
    ('〜間に','The space between two temporal or physical points.','The space between two temporal or physical points.')
),
owner as (
  select user_id from private.app_owner
)
insert into public.japanese_grammar_guides(
  user_id,
  slug,
  pattern,
  meaning,
  summary,
  formation,
  usage,
  nuance,
  register,
  jlpt_level,
  reference_examples,
  reference_links,
  is_placeholder
)
select
  owner.user_id,
  'grammar-'||substr(md5(public.repository_grammar_key(catalogue.canonical)),1,20),
  catalogue.canonical,
  catalogue.meaning,
  catalogue.summary,
  array[]::text[],
  array[]::text[],
  array[]::text[],
  'neutral',
  null,
  '[]'::jsonb,
  '[]'::jsonb,
  false
from catalogue
cross join owner
where not exists (
  select 1
  from public.japanese_grammar_guides existing
  where existing.user_id=owner.user_id
    and existing.pattern_key=public.repository_grammar_key(catalogue.canonical)
);

