owner as (
  select user_id from private.app_owner
),
resolved as (
  select
    owner.user_id,
    guide.id as grammar_id,
    reviewed.entry_id as dictionary_entry_id,
    reviewed.relationship,
    reviewed.volume as source_volume
  from reviewed
  cross join owner
  join public.japanese_grammar_guides guide
    on guide.user_id=owner.user_id
   and guide.pattern_key=public.repository_grammar_key(reviewed.canonical)
  join public.japanese_dictionary_entries dictionary_entry
    on dictionary_entry.user_id=owner.user_id
   and dictionary_entry.id=reviewed.entry_id
)
insert into public.grammar_dictionary_references(
  user_id,
  grammar_id,
  dictionary_entry_id,
  relationship,
  source_volume
)
select
  user_id,
  grammar_id,
  dictionary_entry_id,
  relationship,
  source_volume
from resolved
on conflict(grammar_id,dictionary_entry_id) do update set
  relationship=excluded.relationship,
  source_volume=excluded.source_volume;

commit;

-- Verification: these result sets are read-only.

select
  count(*) as canonical_grammar_guides
from public.japanese_grammar_guides
where user_id=(select user_id from private.app_owner);

select
  count(*) as dojg_reference_links,
  count(distinct dictionary_entry_id) as dojg_entries_linked,
  count(distinct grammar_id) as canonical_guides_with_dojg
from public.grammar_dictionary_references
where user_id=(select user_id from private.app_owner);

select
  g.pattern,
  count(*) as dojg_reference_count,
  string_agg(
    distinct r.source_volume||': '||d.headword,
    ' | '
    order by r.source_volume||': '||d.headword
  ) as dojg_sources
from public.grammar_dictionary_references r
join public.japanese_grammar_guides g
  on g.id=r.grammar_id
join public.japanese_dictionary_entries d
  on d.user_id=r.user_id
 and d.id=r.dictionary_entry_id
where r.user_id=(select user_id from private.app_owner)
group by g.id,g.pattern
having count(*)>1
order by count(*) desc,g.pattern;
